    let _ = checkout(&Order { id: 1, items: vec![("tea", 2), ("cake", 1)] }, &mut stock);
    let _ = checkout(&Order { id: 2, items: vec![("cake", 1)] }, &mut stock);
    let value = dbg!(stock["tea"] * 2);
