use List::{Cons, Nil};

fn values(list: &List) -> Vec<i32> {
    let mut out = Vec::new();
    let mut cur = list;
    while let Cons(v, next) = cur {
        out.push(*v);
        cur = next;
    }
    out
}

fn main() {
