use std::collections::BTreeMap;

#[derive(Debug, Clone, Copy, PartialEq)]
enum Verdict { Passed, Failed, Skipped }

#[derive(Default, Debug)]
struct TestStats { history: Vec<Verdict>, seconds: Vec<f64> }

fn parse(xml: &str) -> Result<Vec<(String, Verdict, f64)>, roxmltree::Error> {
    let doc = roxmltree::Document::parse(xml)?;
    Ok(doc.descendants().filter(|n| n.has_tag_name("testcase")).map(|tc| {
        let has = |t: &str| tc.children().any(|c| c.has_tag_name(t));
        let v = if has("failure") || has("error") { Verdict::Failed } else if has("skipped") { Verdict::Skipped } else { Verdict::Passed };
        let id = format!("{}::{}", tc.attribute("classname").unwrap_or("?"), tc.attribute("name").unwrap_or("?"));
        let secs = tc.attribute("time").and_then(|t| t.replace(',', ".").parse().ok()).unwrap_or(0.0);
        (id, v, secs)
    }).collect())
}

fn main() {
    let runs = [
        r#"<testsuites><testsuite name="login"><testcase classname="login" name="ok" time="0.20"/><testcase classname="login" name="retry" time="1.10"/></testsuite></testsuites>"#,
        r#"<testsuite name="login"><testcase classname="login" name="ok" time="0,25"/><testcase classname="login" name="retry" time="3.40"><failure message="timeout"/></testcase></testsuite>"#,
        r#"<testsuite name="login"><testcase classname="login" name="ok"/><testcase classname="login" name="retry" time="1.30"><error type="ConnectionReset"/></testcase>"#,
        r#"<testsuite name="login"><testcase classname="login" name="ok" time="0.21"/><testcase classname="login" name="retry" time="1.20"/></testsuite>"#,
    ];
    let mut stats: BTreeMap<String, TestStats> = BTreeMap::new();
    for (i, xml) in runs.iter().enumerate() {
        match parse(xml) {
            Ok(cases) => for (id, v, s) in cases {
                let e = stats.entry(id).or_default();
                e.history.push(v);
                e.seconds.push(s);
            },
            Err(err) => println!("run {}: skipped, invalid XML ({err})", i + 1),
        }
    }
    for (id, s) in &stats {
        let mut secs = s.seconds.clone();
        secs.sort_by(f64::total_cmp);
        let passed = s.history.iter().filter(|v| **v == Verdict::Passed).count();
        println!("{id:12} {:?}  pass {}/{}  median {:.2}s", s.history, passed, s.history.len(), secs[secs.len() / 2]);
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Verdict { Passed, Failed, Skipped }

pub fn verdicts(xml: &str) -> Result<Vec<(String, Verdict)>, String> {
    let doc = roxmltree::Document::parse(xml).map_err(|e| e.to_string())?;
    Ok(doc.descendants().filter(|n| n.has_tag_name("testcase")).map(|tc| {
        let has = |t: &str| tc.children().any(|c| c.has_tag_name(t));
        let v = if has("failure") || has("error") { Verdict::Failed } else if has("skipped") { Verdict::Skipped } else { Verdict::Passed };
        (tc.attribute("name").unwrap_or("?").to_string(), v)
    }).collect())
}

