use std::collections::HashSet;

#[derive(Debug, PartialEq)]
enum Finding { Flaky(u32), Regressed, Stable }

fn parse_allow_list(text: &str) -> HashSet<String> {
    text.lines()
        .map(|l| l.split('#').next().unwrap().trim())           // allow comments
        .filter(|l| !l.is_empty())
        .map(String::from)
        .collect()
}

fn gate(results: &[(&str, Finding)], allowed: &HashSet<String>) -> (u8, Vec<String>) {
    let mut report = Vec::new();
    let mut blocking = 0;
    for (id, f) in results {
        match f {
            Finding::Stable => {}
            _ if allowed.contains(*id) => report.push(format!("  known   {id} {f:?}")),
            _ => {
                blocking += 1;
                report.push(format!("  NEW     {id} {f:?}"));
            }
        }
    }
    report.insert(0, format!("{blocking} new problem(s), {} allow-listed", report.len() - blocking));
    (if blocking > 0 { 1 } else { 0 }, report)
}

fn main() {
    let allow = parse_allow_list("# known flaky tests, with tickets\nlogin::sso_redirect   # QA-412 (Kev)\n\ncart::coupon_expiry  # QA-418\n");
    let results = [
        ("login::valid_password", Finding::Stable),
        ("login::sso_redirect", Finding::Flaky(70)),
        ("cart::coupon_expiry", Finding::Flaky(90)),
        ("search::fuzzy_match", Finding::Flaky(55)),
        ("checkout::tax_rounding", Finding::Regressed),
    ];
    let (code, lines) = gate(&results, &allow);
    println!("{}", lines.join("\n"));
    println!("exit code {code}");
    let (code_ok, _) = gate(&results[..3], &allow);
    println!("with only known problems: exit code {code_ok}");
}

fn month_index(m: &str) -> Option<u32> {
    ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"].iter().position(|x| *x == m).map(|i| i as u32)
}

/// Seconds since an arbitrary epoch, good enough for comparing nearby events.
fn parse_ts(line: &str, year: i64) -> Option<i64> {
    let mut parts = line.split_whitespace();
    let month = month_index(parts.next()?)? as i64;
    let day: i64 = parts.next()?.parse().ok()?;
    let hms: Vec<i64> = parts.next()?.split(':').map(|p| p.parse().ok()).collect::<Option<_>>()?;
    let [h, m, s] = hms[..] else { return None };
    const DAYS: [i64; 12] = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
    let leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    let doy = DAYS[month as usize] + day - 1 + if leap && month > 1 { 1 } else { 0 };
    let days_before_year = (year - 1970) * 365 + (year - 1969) / 4 - (year - 1901) / 100 + (year - 1601) / 400;
    Some(((days_before_year + doy) * 86_400) + h * 3600 + m * 60 + s)
}

/// Lines are in order; a jump backwards of months means the year changed.
fn with_rollover(lines: &[&str], start_year: i64) -> Vec<i64> {
    let mut year = start_year;
    let mut last: Option<i64> = None;
    lines.iter().filter_map(|l| {
        let mut t = parse_ts(l, year)?;
        if last.is_some_and(|prev| t < prev - 30 * 86_400) {
            year += 1;
            t = parse_ts(l, year)?;
        }
        last = Some(t);
        Some(t)
    }).collect()
}

fn main() {
    let lines = [
        "Dec 31 23:59:58 web sshd[901]: Failed password for root from 203.0.113.9 port 4000 ssh2",
        "Dec 31 23:59:59 web sshd[902]: Failed password for root from 203.0.113.9 port 4001 ssh2",
        "Jan  1 00:00:01 web sshd[903]: Failed password for root from 203.0.113.9 port 4002 ssh2",
    ];
    let ts = with_rollover(&lines, 2026);
    println!("gaps between events: {:?} seconds", ts.windows(2).map(|w| w[1] - w[0]).collect::<Vec<_>>());
    let naive: Vec<i64> = lines.iter().filter_map(|l| parse_ts(l, 2026)).collect();
    println!("without rollover handling the last gap is {} seconds", naive[2] - naive[1]);
    println!("garbage line parses to {:?}", parse_ts("not a log line", 2026));
}

fn fixed_bucket_alert(times: &[u64], n: usize, w: u64) -> bool {
    let mut counts = std::collections::HashMap::new();
    times.iter().any(|t| {
        let c = counts.entry(t / w).or_insert(0);
        *c += 1;
        *c >= n
    })
}

fn sliding_alert(times: &[u64], n: usize, w: u64) -> bool {
    times.windows(n).any(|win| win[n - 1] - win[0] < w)
}

fn main() {
    let burst = [50, 52, 55, 58, 61, 63, 66];        // 7 failures in 16 seconds, across the 60 s boundary
    println!("rule: 5 failures within 60 s");
    println!("fixed one-minute buckets alert? {}", fixed_bucket_alert(&burst, 5, 60));
    println!("sliding window alerts?          {}", sliding_alert(&burst, 5, 60));
    let slow = [0, 40, 80, 120, 160, 200];            // one failure every 40 s
    println!("slow trickle, sliding window?   {}", sliding_alert(&slow, 5, 60));
}

use regex::Regex;
use std::collections::{HashMap, HashSet, VecDeque};
use std::sync::LazyLock;

static LINE: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"^\S+ +\d+ (\d+):(\d+):(\d+) \S+ sshd\[\d+\]: (Failed|Accepted) \S+ for (?:invalid user )?(\S+) from (\S+) port").unwrap()
});

#[derive(Debug)]
enum Event { Failed { ip: String, ts: u64 }, Accepted { ip: String } }

fn parse(line: &str) -> Option<Event> {
    let c = LINE.captures(line)?;
    let ts = c[1].parse::<u64>().ok()? * 3600 + c[2].parse::<u64>().ok()? * 60 + c[3].parse::<u64>().ok()?;
    let ip = c[6].to_string();
    Some(if &c[4] == "Failed" { Event::Failed { ip, ts } } else { Event::Accepted { ip } })
}

struct Detector { n: usize, window: u64, recent: HashMap<String, VecDeque<u64>>, alerting: HashSet<String> }

impl Detector {
    fn feed(&mut self, e: Event) -> Option<String> {
        match e {
            Event::Accepted { ip } => {
                self.recent.remove(&ip);
                self.alerting.remove(&ip);
                None
            }
            Event::Failed { ip, ts } => {
                let q = self.recent.entry(ip.clone()).or_default();
                q.push_back(ts);
                while q.front().is_some_and(|&t| ts - t >= self.window) {
                    q.pop_front();
                }
                if q.len() < self.n {
                    self.alerting.remove(&ip);
                    None
                } else if self.alerting.insert(ip.clone()) {
                    Some(format!("ALERT {ip}: {} failures in {} s", q.len(), ts - q[0]))
                } else {
                    None
                }
            }
        }
    }
}

fn main() {
    let log = "\
Nov  4 06:12:01 web sshd[1]: Failed password for root from 203.0.113.9 port 1 ssh2
Nov  4 06:12:03 web sshd[2]: Failed password for invalid user admin from 203.0.113.9 port 2 ssh2
Nov  4 06:12:04 web CRON[3]: pam_unix(cron:session): session opened for user root
Nov  4 06:12:05 web sshd[4]: Failed password for kev from 198.51.100.7 port 3 ssh2
Nov  4 06:12:06 web sshd[5]: Failed password for invalid user test from 203.0.113.9 port 4 ssh2
Nov  4 06:12:07 web sshd[6]: Accepted password for kev from 198.51.100.7 port 5 ssh2
Nov  4 06:12:09 web sshd[7]: Failed password for invalid user oracle from 203.0.113.9 port 6 ssh2
Nov  4 06:12:12 web sshd[8]: Failed password for root from 203.0.113.9 port 7 ssh2
Nov  4 06:12:15 web sshd[9]: Failed password for root from 203.0.113.9 port 8 ssh2";
    let mut d = Detector { n: 5, window: 60, recent: HashMap::new(), alerting: HashSet::new() };
    let (mut parsed, mut ignored) = (0, 0);
    for line in log.lines() {
        match parse(line) {
            Some(e) => {
                parsed += 1;
                if let Some(alert) = d.feed(e) { println!("{alert}"); }
            }
            None => ignored += 1,
        }
    }
    println!("{parsed} events, {ignored} ignored line; IPs still tracked: {:?}", d.recent.keys().collect::<Vec<_>>());
}

use std::collections::{HashMap, VecDeque};

pub struct Detector { n: usize, window: u64, recent: HashMap<String, VecDeque<u64>> }

impl Detector {
    pub fn new(n: usize, window: u64) -> Self { Detector { n, window, recent: HashMap::new() } }

    pub fn failed(&mut self, ip: &str, ts: u64) -> bool {
        let q = self.recent.entry(ip.to_string()).or_default();
        q.push_back(ts);
        while q.front().is_some_and(|&t| ts - t >= self.window) { q.pop_front(); }
        q.len() >= self.n
    }

    pub fn accepted(&mut self, ip: &str) { self.recent.remove(ip); }

    pub fn tracked(&self) -> usize { self.recent.len() }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn window_boundary_is_exclusive() {
        let mut d = Detector::new(3, 10);
        assert!(!d.failed("a", 0));
        assert!(!d.failed("a", 5));
        assert!(!d.failed("a", 10), "the event at t=0 is exactly 10 s old and has expired");
        assert!(d.failed("a", 11));
    }

    #[test]
    fn success_resets_history() {
        let mut d = Detector::new(3, 60);
        d.failed("a", 1);
        d.failed("a", 2);
        d.accepted("a");
        assert!(!d.failed("a", 3));
        assert_eq!(d.tracked(), 1);
    }

    #[test]
    fn ips_are_independent_including_ipv6() {
        let mut d = Detector::new(2, 60);
        assert!(!d.failed("2001:db8::1", 1));
        assert!(!d.failed("203.0.113.9", 2));
        assert!(d.failed("2001:db8::1", 3));
    }

    #[test]
    fn slow_attempts_never_alert() {
        let mut d = Detector::new(3, 60);
        assert!((0..20).all(|i| !d.failed("a", i * 31)));
    }
}

use std::fs::{File, OpenOptions};
use std::io::{BufRead, BufReader, Seek, SeekFrom, Write};
use std::thread;
use std::time::Duration;

struct Follower { path: std::path::PathBuf, reader: BufReader<File>, pos: u64 }

impl Follower {
    fn open_at_end(path: &std::path::Path) -> std::io::Result<Self> {
        let mut f = File::open(path)?;
        let pos = f.seek(SeekFrom::End(0))?;
        Ok(Follower { path: path.into(), reader: BufReader::new(f), pos })
    }

    /// Returns any complete new lines; reopens from the start if the file was truncated.
    fn poll(&mut self) -> std::io::Result<Vec<String>> {
        let len = std::fs::metadata(&self.path)?.len();
        if len < self.pos {
            println!("  (file truncated: reopening from the start)");
            let f = File::open(&self.path)?;
            self.reader = BufReader::new(f);
            self.pos = 0;
        }
        let mut lines = Vec::new();
        let mut line = String::new();
        while self.reader.read_line(&mut line)? > 0 {
            if !line.ends_with('\n') {                       // a partial line: wait for the rest
                self.reader.seek(SeekFrom::Start(self.pos))?;
                break;
            }
            self.pos += line.len() as u64;
            lines.push(line.trim_end().to_string());
            line.clear();
        }
        Ok(lines)
    }
}

fn main() -> std::io::Result<()> {
    let path = std::env::temp_dir().join(format!("logwatch-demo-{}.log", std::process::id()));
    std::fs::write(&path, "old line, before we started\n")?;
    let mut follower = Follower::open_at_end(&path)?;

    let writer_path = path.clone();
    let writer = thread::spawn(move || -> std::io::Result<()> {
        let mut f = OpenOptions::new().append(true).open(&writer_path)?;
        writeln!(f, "Failed password for root from 203.0.113.9")?;
        write!(f, "Failed password for adm")?;                // half a line...
        f.flush()?;
        thread::sleep(Duration::from_millis(60));
        writeln!(f, "in from 203.0.113.9")?;                // ...completed later
        thread::sleep(Duration::from_millis(60));
        std::fs::write(&writer_path, "")?;                  // logrotate-style truncation
        let mut f = OpenOptions::new().append(true).open(&writer_path)?;
        writeln!(f, "Accepted publickey for kev from 198.51.100.7")?;
        Ok(())
    });

    for _ in 0..12 {
        for line in follower.poll()? {
            println!("new line: {line}");
        }
        thread::sleep(Duration::from_millis(25));
    }
    writer.join().unwrap()?;
    std::fs::remove_file(&path)?;
    Ok(())
}

use serde::Deserialize;

#[derive(Debug, Deserialize)]
#[serde(default)]
struct ListQuery {
    page: u32,
    per_page: u32,
    status: Option<Status>,
}

#[derive(Debug, Deserialize, Clone, Copy, PartialEq)]
#[serde(rename_all = "lowercase")]
enum Status { Open, Done }

impl Default for ListQuery {
    fn default() -> Self { ListQuery { page: 1, per_page: 20, status: None } }
}

impl ListQuery {
    const MAX_PER_PAGE: u32 = 100;
    fn normalised(self) -> Self {
        ListQuery { page: self.page.max(1), per_page: self.per_page.clamp(1, Self::MAX_PER_PAGE), ..self }
    }
    fn sql_window(&self) -> (u32, u32) {
        (self.per_page, (self.page - 1) * self.per_page)          // LIMIT, OFFSET
    }
}

fn pages(total: u32, per_page: u32) -> u32 { total.div_ceil(per_page).max(1) }

fn main() {
    for qs in ["", "page=3", "page=0&per_page=5000", "status=done&per_page=10&page=2", "status=archived"] {
        match serde_urlencoded::from_str::<ListQuery>(qs) {
            Ok(q) => {
                let q = q.normalised();
                let (limit, offset) = q.sql_window();
                println!("{:34} -> page {} per_page {} status {:?}: LIMIT {limit} OFFSET {offset}", format!("?{qs}"), q.page, q.per_page, q.status);
            }
            Err(e) => println!("{:34} -> 422 {{\"error\":\"{e}\"}}", format!("?{qs}")),
        }
    }
    println!("57 tasks at 20 per page = {} pages", pages(57, 20));
}

use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq)]
struct Task { id: u64, title: String, done: bool }

trait TaskRepo {
    fn insert(&mut self, title: &str) -> Task;
    fn get(&self, id: u64) -> Option<Task>;
    fn set_done(&mut self, id: u64, done: bool) -> Option<Task>;
}

#[derive(Default)]
struct MemoryRepo { rows: BTreeMap<u64, Task> }

impl TaskRepo for MemoryRepo {
    fn insert(&mut self, title: &str) -> Task {
        let id = self.rows.len() as u64 + 1;
        let t = Task { id, title: title.into(), done: false };
        self.rows.insert(id, t.clone());
        t
    }
    fn get(&self, id: u64) -> Option<Task> { self.rows.get(&id).cloned() }
    fn set_done(&mut self, id: u64, done: bool) -> Option<Task> {
        let t = self.rows.get_mut(&id)?;
        t.done = done;
        Some(t.clone())
    }
}

#[derive(Debug, PartialEq)]
enum ServiceError { Validation(String), NotFound(u64) }

struct TaskService<R: TaskRepo> { repo: R }

impl<R: TaskRepo> TaskService<R> {
    fn create(&mut self, title: &str) -> Result<Task, ServiceError> {
        let title = title.trim();
        if title.is_empty() {
            return Err(ServiceError::Validation("title must not be empty".into()));
        }
        if title.chars().count() > 200 {
            return Err(ServiceError::Validation("title must be at most 200 characters".into()));
        }
        Ok(self.repo.insert(title))
    }
    fn complete(&mut self, id: u64) -> Result<Task, ServiceError> {
        self.repo.set_done(id, true).ok_or(ServiceError::NotFound(id))
    }
}

fn main() {
    let mut svc = TaskService { repo: MemoryRepo::default() };
    println!("{:?}", svc.create("  Write the README  "));
    println!("{:?}", svc.create("   "));
    println!("{:?}", svc.create(&"x".repeat(201)).map(|t| t.id));
    println!("{:?}", svc.complete(1));
    println!("{:?}", svc.complete(42));
    println!("stored: {:?}", svc.repo.get(1));
}

use rusqlite::{params, Connection, OptionalExtension, Result, Row};

#[derive(Debug)]
struct Task { id: i64, title: String, done: bool }

fn row_to_task(row: &Row) -> Result<Task> {
    Ok(Task { id: row.get("id")?, title: row.get("title")?, done: row.get("done")? })
}

struct Repo { conn: Connection }

impl Repo {
    fn open_in_memory() -> Result<Self> {
        let conn = Connection::open_in_memory()?;
        conn.execute_batch("CREATE TABLE tasks (id INTEGER PRIMARY KEY, title TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0);")?;
        Ok(Repo { conn })
    }
    fn create(&self, title: &str) -> Result<Task> {
        self.conn.execute("INSERT INTO tasks (title) VALUES (?1)", params![title])?;
        self.get(self.conn.last_insert_rowid()).map(|t| t.unwrap())
    }
    fn get(&self, id: i64) -> Result<Option<Task>> {
        self.conn.query_row("SELECT id, title, done FROM tasks WHERE id = ?1", params![id], row_to_task).optional()
    }
    fn list(&self, page: u32, per_page: u32) -> Result<(Vec<Task>, i64)> {
        let mut stmt = self.conn.prepare("SELECT id, title, done FROM tasks ORDER BY id LIMIT ?1 OFFSET ?2")?;
        let items = stmt.query_map(params![per_page, (page - 1) * per_page], row_to_task)?.collect::<Result<Vec<_>>>()?;
        let total = self.conn.query_row("SELECT COUNT(*) FROM tasks", [], |r| r.get(0))?;
        Ok((items, total))
    }
    fn patch(&self, id: i64, title: Option<&str>, done: Option<bool>) -> Result<Option<Task>> {
        let changed = self.conn.execute(
            "UPDATE tasks SET title = COALESCE(?1, title), done = COALESCE(?2, done) WHERE id = ?3",
            params![title, done, id],
        )?;
        if changed == 0 { Ok(None) } else { self.get(id) }
    }
}

fn main() -> Result<()> {
    let repo = Repo::open_in_memory()?;
    for t in ["Write tests", "Add pagination", "Dockerfile", "README", "Release"] {
        repo.create(t)?;
    }
    let (page2, total) = repo.list(2, 2)?;
    println!("page 2 of {total}: {page2:?}");
    println!("patch done only:  {:?}", repo.patch(3, None, Some(true))?);
    println!("patch title only: {:?}", repo.patch(3, Some("Multi-stage Dockerfile"), None)?);
    println!("patch missing id: {:?}", repo.patch(99, None, Some(true))?);
    println!("get missing id:   {:?}", repo.get(99)?);
    Ok(())
}

use axum::{body::Body, extract::{Path, State}, http::{Request, StatusCode}, response::{IntoResponse, Response}, routing::{get, post}, Json, Router};
use http_body_util::BodyExt;
use rusqlite::{params, Connection, OptionalExtension};
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::sync::{Arc, Mutex};
use tower::ServiceExt;

#[derive(Serialize)]
struct Task { id: i64, title: String, done: bool }

#[derive(Deserialize)]
struct NewTask { title: String }

enum ApiError { NotFound(i64), Validation(String), Internal(String) }

impl From<rusqlite::Error> for ApiError {
    fn from(e: rusqlite::Error) -> Self { ApiError::Internal(e.to_string()) }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let (status, msg) = match self {
            ApiError::NotFound(id) => (StatusCode::NOT_FOUND, format!("task {id} not found")),
            ApiError::Validation(m) => (StatusCode::UNPROCESSABLE_ENTITY, m),
            ApiError::Internal(_) => (StatusCode::INTERNAL_SERVER_ERROR, "internal error".into()),
        };
        (status, Json(json!({ "error": msg }))).into_response()
    }
}

type Db = Arc<Mutex<Connection>>;

async fn create(State(db): State<Db>, Json(new): Json<NewTask>) -> Result<(StatusCode, Json<Task>), ApiError> {
    let title = new.title.trim().to_string();
    if title.is_empty() {
        return Err(ApiError::Validation("title must not be empty".into()));
    }
    let conn = db.lock().unwrap();
    conn.execute("INSERT INTO tasks (title) VALUES (?1)", params![title])?;
    Ok((StatusCode::CREATED, Json(Task { id: conn.last_insert_rowid(), title, done: false })))
}

async fn show(State(db): State<Db>, Path(id): Path<i64>) -> Result<Json<Task>, ApiError> {
    let conn = db.lock().unwrap();
    conn.query_row("SELECT id, title, done FROM tasks WHERE id = ?1", params![id], |r| Ok(Task { id: r.get(0)?, title: r.get(1)?, done: r.get(2)? }))
        .optional()?
        .map(Json)
        .ok_or(ApiError::NotFound(id))
}

fn app() -> Router {
    let conn = Connection::open_in_memory().unwrap();
    conn.execute_batch("CREATE TABLE tasks (id INTEGER PRIMARY KEY, title TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0);").unwrap();
    Router::new()
        .route("/health", get(|| async { Json(json!({"status": "ok"})) }))
        .route("/tasks", post(create))
        .route("/tasks/{id}", get(show))
        .with_state(Arc::new(Mutex::new(conn)))
}

async fn send(app: &Router, method: &str, uri: &str, body: &str) -> (u16, String) {
    let req = Request::builder().method(method).uri(uri).header("content-type", "application/json").body(Body::from(body.to_string())).unwrap();
    let resp = app.clone().oneshot(req).await.unwrap();
    let status = resp.status().as_u16();
    (status, String::from_utf8(resp.into_body().collect().await.unwrap().to_bytes().to_vec()).unwrap())
}

#[tokio::main]
async fn main() {
    let app = app();
    let checks = [
        ("GET", "/health", "", 200),
        ("POST", "/tasks", r#"{"title":"Write tests"}"#, 201),
        ("POST", "/tasks", r#"{"title":"   "}"#, 422),
        ("GET", "/tasks/1", "", 200),
        ("GET", "/tasks/9", "", 404),
    ];
    for (method, uri, body, expected) in checks {
        let (status, text) = send(&app, method, uri, body).await;
        let mark = if status == expected { "pass" } else { "FAIL" };
        println!("{mark} {method:4} {uri:9} {status} {text}");
    }
}

